with ins_talas as (
  insert into public.vms_beats_talas (name, beats_count, display_order) values
    ('Teen Taal', 16, 0),
    ('Do Taal', null, 1),
    ('Changing Speeds', null, 2)
  returning id, name
),
ins_sets as (
  insert into public.vms_beats_practice_sets (tala_id, title, tempo_label, bpm_min, bpm_max, is_paid, display_order)
  select t.id, v.title, v.tempo_label, v.bpm_min, v.bpm_max, v.is_paid, v.display_order
  from (values
    ('Teen Taal', 'Teen Taal · Slow · Kartal', 'beginner', 90, 200, false, 0),
    ('Teen Taal', 'Teen Taal · Slow · Kartal & Mridanga', 'beginner', 100, 200, false, 1),
    ('Teen Taal', 'Teen Taal · Slow · Kartal & Mridanga with Tehai', 'beginner', 100, 200, false, 2),
    ('Teen Taal', 'Teen Taal · Fast · Kartal', 'practice', 150, 230, true, 3),
    ('Teen Taal', 'Teen Taal · Fast · Kartal & Mridanga', 'practice', 90, 140, true, 4),
    ('Do Taal', 'Do Taal · Slow · Kartal', 'beginner', 80, 180, true, 5),
    ('Do Taal', 'Do Taal · Slow · Kartal & Mridanga', 'beginner', 75, 170, true, 6),
    ('Do Taal', 'Do Taal · Fast · Kartal', 'practice', 100, 180, true, 7),
    ('Do Taal', 'Do Taal · Fast · Kartal & Mridanga', 'practice', 110, 180, true, 8),
    ('Changing Speeds', 'Changing Speeds · Long · Kartal & Mridanga', 'performance', 60, 200, true, 9),
    ('Changing Speeds', 'Changing Speeds · Short · Kartal & Mridanga', 'performance', 60, 200, true, 10)
  ) as v(tala_name, title, tempo_label, bpm_min, bpm_max, is_paid, display_order)
  join ins_talas t on t.name = v.tala_name
  returning id, title
)
